import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { familyFor } from "@/lib/game-config";
import { PageShell } from "@/components/nx/PageShell";
import { StoreBrowser } from "@/components/mods/StoreBrowser";
import type { QuickAddServer } from "@/components/mods/QuickAddButton";
import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { listCatalogFamilies, listCatalogMods, formatDownloads } from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

/** Portal's own per-game NxLabs page — same data as the marketing one, own chrome/route (item 7). */
export default async function PortalGameModsPage({ params }: { params: Promise<{ family: string }> }) {
  const { family } = await params;
  const user = await requireUser();

  const families = await listCatalogFamilies();
  const entry = families.find((f) => f.family === family);
  if (!entry) notFound();

  const [mods, myServers] = await Promise.all([
    listCatalogMods(family),
    db.server.findMany({ where: { userId: user.id, status: { notIn: ["DELETING"] } }, include: { osTemplate: true, gamePlan: true } }),
  ]);

  const myMatchingServers: QuickAddServer[] = myServers
    .filter((s) => familyFor(s) === family)
    .map((s) => ({ id: s.id, hostname: s.hostname, label: s.label }));

  const label = GAME_DISPLAY[family as GameFamily]?.name ?? entry.label;
  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;
  const totalDownloads = mods.reduce((sum, m) => sum + (m.downloads ?? 0), 0);

  const categoryCounts = new Map<string, number>();
  for (const m of mods) categoryCounts.set(m.category, (categoryCounts.get(m.category) ?? 0) + 1);
  const chips = [...categoryCounts.entries()].sort((a, b) => b[1] - a[1]).map(([category, count]) => ({ key: category, label: category, count }));

  return (
    <PageShell
      eyebrow="NxLabs"
      title={`${label} mods & plugins`}
      sub={`${entry.count} verified add-ons for ${label}${totalDownloads > 0 ? ` — ${formatDownloads(totalDownloads)} total downloads` : ""}.`}
      tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}
      heroImage={heroSlug ? `/games/art/${heroSlug}_hero.jpg` : undefined}
    >
      <StoreBrowser
        mods={mods}
        chips={chips}
        chipField="category"
        basePath="/dashboard/nxlabs"
        searchPlaceholder={`Search ${label} mods…`}
        serversByFamily={{ [family]: myMatchingServers }}
        deployHref="/dashboard/deploy"
      />
    </PageShell>
  );
}

=== marketing detail page ===
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { Section } from "@/components/marketing/primitives";
import { ModCard } from "@/components/mods/ModCard";
import { AddToServerWidget } from "@/components/mods/AddToServerWidget";
import { AuthorBadge } from "@/components/mods/AuthorBadge";
import { GalleryStrip } from "@/components/mods/GalleryStrip";
import { RatingsAndComments } from "@/components/mods/RatingsAndComments";
import { APP_URL } from "@/components/marketing/StructuredData";
import {
  getCatalogMod,
  listCatalogSlugs,
  relatedCatalogMods,
  recommendedPlanFor,
  resolveDownloadUrl,
  listModComments,
  getMyModRating,
  formatDownloads,
  formatBytes,
  SOURCE_LABEL,
} from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

type Params = { params: Promise<{ family: string; slug: string }> };

export async function generateStaticParams(): Promise<Array<{ family: string; slug: string }>> {
  return listCatalogSlugs();
}

export async function generateMetadata({ params }: Params): Promise<Metadata> {
  const { family, slug } = await params;
  const mod = await getCatalogMod(family, slug);
  if (!mod) return { title: "Mod not found" };
  const title = `${mod.name} — ${mod.gameFamilyLabel} ${mod.category} | NxLabs`;
  const description =
    mod.description ||
    `${mod.name} for ${mod.gameFamilyLabel}, verified against ${SOURCE_LABEL[mod.source] ?? mod.source} — real download counts, supported versions, and a direct download link.`;
  return {
    title,
    description,
    alternates: { canonical: `/mods/${mod.gameFamily}/${mod.slug}` },
    openGraph: {
      title,
      description,
      type: "website",
      url: `${APP_URL}/mods/${mod.gameFamily}/${mod.slug}`,
      ...(mod.iconUrl ? { images: [mod.iconUrl] } : {}),
    },
  };
}

export default async function ModDetailPage({ params }: Params) {
  const { family, slug } = await params;
  const mod = await getCatalogMod(family, slug);
  if (!mod) notFound();

  const user = await currentUser();
  const [gamePlans, related, download, commentsPage, myRating] = await Promise.all([
    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
    relatedCatalogMods(mod, 4),
    resolveDownloadUrl(mod),
    listModComments(mod.id, { take: 10 }),
    user ? getMyModRating(mod.id, user.id) : Promise.resolve(null),
  ]);
  const recommended = recommendedPlanFor(mod, gamePlans);
  const downloads = formatDownloads(mod.downloads);
  const fileSize = formatBytes(mod.fileBytes);
  const heroImage = mod.galleryUrls[0] ?? mod.iconUrl ?? null;

  return (
    <>
      {/* SoftwareApplication, not Product — this is a free, third-party-hosted
          download, not something Nxeon sells. price: "0" is the accurate,
          Google-documented way to mark a free application. aggregateRating is
          now real (ModRating), so it's included ONLY when at least one exists
          — never a fabricated 0/0. */}
      <script
        type="application/ld+json"
        // eslint-disable-next-line react/no-danger
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "SoftwareApplication",
            name: mod.name,
            applicationCategory: "GameApplication",
            operatingSystem: mod.gameFamilyLabel,
            description: mod.description || `${mod.name} for ${mod.gameFamilyLabel}.`,
            ...(mod.iconUrl ? { image: mod.iconUrl } : {}),
            ...(download ? { downloadUrl: download.url } : {}),
            offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
            ...(mod.avgRating != null
              ? {
                  aggregateRating: {
                    "@type": "AggregateRating",
                    ratingValue: mod.avgRating.toFixed(1),
                    reviewCount: mod.ratingCount,
                  },
                }
              : {}),
          }),
        }}
      />

      <section className="relative overflow-hidden">
        {heroImage && (
          <div className="absolute inset-0 -z-10">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={heroImage} alt="" className="h-full w-full object-cover opacity-25 blur-sm" />
            <div className="absolute inset-0 bg-gradient-to-t from-[var(--bg)] via-[var(--bg)]/80 to-[var(--bg)]/40" />
          </div>
        )}
        <div className="rail py-16 sm:py-20">
          <p className="text-xs font-semibold uppercase tracking-widest text-brand-300">
            <Link href="/mods" className="hover:underline">
              NxLabs
            </Link>{" "}
            /{" "}
            <Link href={`/mods/games/${mod.gameFamily}`} className="hover:underline">
              {mod.gameFamilyLabel}
            </Link>
          </p>
          <div className="mt-3 flex flex-wrap items-center gap-4">
            {mod.iconUrl && (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={mod.iconUrl} alt="" className="h-16 w-16 rounded-2xl border border-white/10 object-cover" />
            )}
            <div>
              <h1 className="text-3xl font-bold text-[var(--fg)] sm:text-4xl">{mod.name}</h1>
              {mod.authorName && (
                <div className="mt-1">
                  <AuthorBadge name={mod.authorName} avatarUrl={mod.authorAvatarUrl} />
                </div>
              )}
            </div>
          </div>
          {mod.description && <p className="mt-4 max-w-2xl text-[var(--fg-muted)]">{mod.description}</p>}
        </div>
      </section>

      <Section>
        <div className="mx-auto grid max-w-5xl gap-8 lg:grid-cols-[1.4fr_1fr]">
          <div className="space-y-6">
            {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}

            <div className="card p-6">
              <h2 className="text-lg font-semibold text-[var(--fg)]">Download</h2>
              {download ? (
                <>
                  <a href={download.url} className="btn-primary mt-4 inline-flex" target="_blank" rel="noopener noreferrer nofollow">
                    {download.direct ? "Download file" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
                  </a>
                  <p className="mt-2 text-xs text-[var(--fg-muted)]">
                    Hosted by {SOURCE_LABEL[mod.source] ?? mod.source} — Nxeon never mirrors or stores mod files.
                  </p>
                </>
              ) : (
                <p className="mt-3 text-sm text-[var(--fg-muted)]">No download link is available for this entry right now.</p>
              )}

              <div className="mt-6">
                <AddToServerWidget modId={mod.id} gameFamily={mod.gameFamilyLabel} downloadUrl={download?.url ?? null} />
              </div>

              {!mod.upstreamOk && (
                <p className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
                  {mod.upstreamNote || "This mod is no longer supported by its source."}
                </p>
              )}
            </div>

            <RatingsAndComments
              modId={mod.id}
              avgRating={mod.avgRating}
              ratingCount={mod.ratingCount}
              initialComments={commentsPage.comments}
              initialCursor={commentsPage.nextCursor}
              myRating={myRating}
              isLoggedIn={!!user}
              isAdmin={user?.role === "ADMIN"}
              loginHref={`/login?next=${encodeURIComponent(`/mods/${mod.gameFamily}/${mod.slug}`)}`}
            />
          </div>

          <aside className="space-y-6">
            <div className="card p-6">
              <h2 className="text-sm font-semibold uppercase tracking-wide text-[var(--fg-muted)]">Details</h2>
              <dl className="mt-4 space-y-3 text-sm">
                <Row label="Game">{mod.gameFamilyLabel}</Row>
                <Row label="Category">{mod.category}</Row>
                <Row label="Source">{SOURCE_LABEL[mod.source] ?? mod.source}</Row>
                {mod.license && <Row label="License">{mod.license}</Row>}
                {downloads && <Row label="Downloads">{downloads}</Row>}
                {fileSize && <Row label="File size">{fileSize}</Row>}
                {mod.gameVersions.length > 0 && (
                  <Row label="Game versions">{mod.gameVersions.slice(-6).reverse().join(", ")}</Row>
                )}
                {mod.loaders.length > 0 && <Row label="Loaders">{mod.loaders.join(", ")}</Row>}
                {mod.appliesToVariant && <Row label="Requires">{mod.appliesToVariant} server type</Row>}
                {mod.serverSide && <Row label="Server support">{mod.serverSide}</Row>}
                <Row label="Verified">
                  {mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}
                </Row>
              </dl>
            </div>

            <div className="card p-6">
              <h2 className="text-sm font-semibold uppercase tracking-wide text-[var(--fg-muted)]">Recommended server</h2>
              {recommended ? (
                <p className="mt-3 text-sm text-[var(--fg-muted)]">
                  Works well on <span className="text-[var(--fg)]">{recommended.planName}</span> (
                  {(recommended.ramMB / 1024).toFixed(recommended.ramMB % 1024 ? 1 : 0)} GB RAM) or higher —{" "}
                  <Link href={`/${mod.gameFamily}-server-hosting`} className="text-brand-300 underline underline-offset-2">
                    see plans
                  </Link>
                  .
                </p>
              ) : (
                <p className="mt-3 text-sm text-[var(--fg-muted)]">
                  {mod.impactNote || "This is a light install and should run fine on any active plan for this game."}
                </p>
              )}
            </div>
          </aside>
        </div>

        {related.length > 0 && (
          <div className="mx-auto mt-16 max-w-5xl">
            <h2 className="text-lg font-semibold text-[var(--fg)]">More for {mod.gameFamilyLabel}</h2>
            <div className="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {related.map((r) => (
                <ModCard key={r.id} mod={r} href={`/mods/${r.gameFamily}/${r.slug}`} />
              ))}
            </div>
          </div>
        )}
      </Section>
    </>
  );
}

function Row({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex items-start justify-between gap-4">
      <dt className="text-[var(--fg-muted)]">{label}</dt>
      <dd className="text-right text-[var(--fg)]">{children}</dd>
    </div>
  );
}

