1	/**
2	 * NxLabs — the public + in-portal mod/plugin catalogue read layer.
3	 *
4	 * This is a thin, presentation-agnostic layer over the REAL `GameMod` table
5	 * (seeded rows, enriched by scripts/verify-gamemods.ts). It backs three call
6	 * sites that must never disagree about what a mod "is":
7	 *   - app/(marketing)/mods (public browse + detail pages, anonymous-visible)
8	 *   - app/dashboard/nxlabs (logged-in catalogue with "Add to my server")
9	 *   - app/sitemap.ts (which detail pages get indexed)
10	 *
11	 * Deliberately NOT here: install/uninstall. Those stay exactly where they are
12	 * — lib/actions-mods.ts's installMod/uninstallMod — this module only reads.
13	 *
14	 * HONESTY: a mod only appears in the public/portal catalogue when
15	 * `active && upstreamOk`. `upstreamOk: false` is scripts/verify-gamemods.ts's
16	 * (or an admin's manual toggle's) way of saying "no longer supported" — it is
17	 * excluded rather than shown with a broken badge, matching how
18	 * lib/actions-mods.ts's getServerMods already filters for the per-server
19	 * panel. Fields the source never published (gameVersions, license, ...) stay
20	 * empty and the UI says so — never a guess.
21	 *
22	 * SCALE CAP (added alongside scripts/import-modrinth-catalog.ts, 2026-09):
23	 * every comment in this file used to say "small catalogue (~124 rows), the
24	 * whole set is returned in one shot, filters run client-side" — true when
25	 * this was hand-seeded, false the moment a real bulk import lands thousands
26	 * of real Modrinth rows in one family. `listCatalogMods`/`searchCatalogMods`
27	 * cap what they return (`CATALOG_LIST_CAP`) rather than serializing an
28	 * unbounded table into a client component's props on every page load. The
29	 * existing ordering (featured, then downloads, then popularity/name) already
30	 * puts the best content first, so a cap degrades gracefully — visitors see
31	 * the best few hundred, not a random slice — but it is a stopgap, not real
32	 * pagination/search-on-the-server; a follow-up should give StoreBrowser a
33	 * real paginated/searched data source once a family regularly exceeds this.
34	 */
35	import { db } from "./db";
36	import type { GameMod, GamePlan } from "@prisma/client";
37	import { GAME_DISPLAY, type GameFamily } from "./games";
38	
39	/** See "SCALE CAP" note above. Small/curated families are never affected by this. */
40	const CATALOG_LIST_CAP = 400;
41	
42	export type ModSummary = {
43	  id: string;
44	  gameFamily: string;
45	  gameFamilyLabel: string;
46	  name: string;
47	  slug: string;
48	  category: string;
49	  source: string;
50	  iconUrl: string | null;
51	  description: string | null;
52	  downloads: number | null;
53	  featured: boolean;
54	  paid: boolean;
55	  verified: boolean;
56	  impact: string;
57	  createdAt: string; // ISO — client components get plain data, not Date objects
58	  /** Real computed average (1-5) from ModRating, null when nobody has rated it yet. */
59	  avgRating: number | null;
60	  /** Real count backing avgRating — 0 means "no ratings", never hidden behind a fake avg. */
61	  ratingCount: number;
62	};
63	
64	export type ModDetail = ModSummary & {
65	  url: string | null;
66	  sourceId: string | null;
67	  license: string | null;
68	  gameVersions: string[];
69	  loaders: string[];
70	  fileBytes: number | null;
71	  dependencyCount: number;
72	  serverSide: string | null;
73	  impactNote: string | null;
74	  appliesToVariant: string | null;
75	  verifiedAt: Date | null;
76	  upstreamOk: boolean;
77	  upstreamNote: string | null;
78	  galleryUrls: string[];
79	  authorName: string | null;
80	  authorAvatarUrl: string | null;
81	};
82	
83	export type ModComment = {
84	  id: string;
85	  rating: number;
86	  comment: string;
87	  createdAt: string;
88	  userId: string;
89	  userName: string;
90	};
91	
92	function familyLabel(family: string): string {
93	  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
94	}
95	
96	type RatingAgg = { avg: number | null; count: number };
97	
98	/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
99	async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
100	  if (modIds.length === 0) return new Map();
101	  const rows = await db.modRating.groupBy({
102	    by: ["gameModId"],
103	    where: { gameModId: { in: modIds } },
104	    _avg: { rating: true },
105	    _count: { rating: true },
106	  });
107	  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
108	}
109	
110	function toSummary(m: GameMod, agg?: RatingAgg): ModSummary {
111	  return {
112	    id: m.id,
113	    gameFamily: m.gameFamily,
114	    gameFamilyLabel: familyLabel(m.gameFamily),
115	    name: m.name,
116	    slug: m.slug,
117	    category: m.category,
118	    source: m.source,
119	    iconUrl: m.iconUrl,
120	    description: m.description,
121	    downloads: m.downloads,
122	    featured: m.featured,
123	    paid: m.paid,
124	    verified: m.verifiedAt !== null,
125	    impact: m.impact,
126	    createdAt: m.createdAt.toISOString(),
127	    avgRating: agg?.avg ?? null,
128	    ratingCount: agg?.count ?? 0,
129	  };
130	}
131	
132	function toDetail(m: GameMod, agg?: RatingAgg): ModDetail {
133	  return {
134	    ...toSummary(m, agg),
135	    url: m.url,
136	    sourceId: m.sourceId,
137	    license: m.license,
138	    gameVersions: m.gameVersions,
139	    loaders: m.loaders,
140	    fileBytes: m.fileBytes,
141	    dependencyCount: m.dependencyCount,
142	    serverSide: m.serverSide,
143	    impactNote: m.impactNote,
144	    appliesToVariant: m.appliesToVariant,
145	    verifiedAt: m.verifiedAt,
146	    upstreamOk: m.upstreamOk,
147	    upstreamNote: m.upstreamNote,
148	    galleryUrls: m.galleryUrls,
149	    authorName: m.authorName,
150	    authorAvatarUrl: m.authorAvatarUrl,
151	  };
152	}
153	
154	/** Real, publicly-listable families — active mods with a real upstream today. */
155	export async function listCatalogFamilies(): Promise<{ family: string; label: string; count: number }[]> {
156	  const rows = await db.gameMod.groupBy({
157	    by: ["gameFamily"],
158	    where: { active: true, upstreamOk: true },
159	    _count: true,
160	    orderBy: { gameFamily: "asc" },
161	  });
162	  return rows
163	    .map((r) => ({ family: r.gameFamily, label: familyLabel(r.gameFamily), count: r._count }))
164	    .sort((a, b) => b.count - a.count);
165	}
166	
167	/**
168	 * Browse listing, optionally scoped to one family. Small catalogue (~124
169	 * rows) — the whole set is returned in one shot and every filter/sort/search
170	 * control on top of it (StoreBrowser) runs client-side over this array
171	 * rather than round-tripping the server, which is what makes those controls
172	 * feel instant instead of decorative.
173	 */
174	export async function listCatalogMods(family?: string): Promise<ModSummary[]> {
175	  const rows = await db.gameMod.findMany({
176	    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
177	    orderBy: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
178	    take: CATALOG_LIST_CAP,
179	  });
180	  const aggs = await ratingAggs(rows.map((r) => r.id));
181	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
182	}
183	
184	/** Every {family, slug} pair eligible for a public page — feeds generateStaticParams + sitemap.ts. */
185	export async function listCatalogSlugs(): Promise<{ family: string; slug: string }[]> {
186	  const rows = await db.gameMod.findMany({
187	    where: { active: true, upstreamOk: true },
188	    select: { gameFamily: true, slug: true },
189	  });
190	  return rows.map((r) => ({ family: r.gameFamily, slug: r.slug }));
191	}
192	
193	/** One mod's detail. Returns null for an unknown/inactive slug — callers should notFound(). */
194	export async function getCatalogMod(family: string, slug: string): Promise<ModDetail | null> {
195	  const row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
196	  if (!row || !row.active) return null;
197	  const aggs = await ratingAggs([row.id]);
198	  return toDetail(row, aggs.get(row.id));
199	}
200	
201	/** A handful of other mods in the same family, for "related mods" rails. */
202	export async function relatedCatalogMods(mod: ModDetail, take = 4): Promise<ModSummary[]> {
203	  const rows = await db.gameMod.findMany({
204	    where: { active: true, upstreamOk: true, gameFamily: mod.gameFamily, id: { not: mod.id } },
205	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }],
206	    take: take * 3, // over-fetch a little so the same-category re-sort below has real options
207	  });
208	  const aggs = await ratingAggs(rows.map((r) => r.id));
209	  // Prefer same-category matches first, client-side sort (small result set).
210	  return rows
211	    .map((r) => toSummary(r, aggs.get(r.id)))
212	    .sort((a, b) => Number(b.category === mod.category) - Number(a.category === mod.category))
213	    .slice(0, take);
214	}
215	
216	/**
217	 * Real average rating + comment count for one mod, and its paginated,
218	 * genuinely user-authored comment list (ModRating rows with a non-null
219	 * `comment`). No fabricated numbers: a mod nobody has rated returns
220	 * avg: null, count: 0, comments: [].
221	 */
222	export async function getModRatingSummary(modId: string): Promise<{ avg: number | null; count: number }> {
223	  const agg = await db.modRating.aggregate({ where: { gameModId: modId }, _avg: { rating: true }, _count: { rating: true } });
224	  return { avg: agg._avg.rating, count: agg._count.rating };
225	}
226	
227	export async function listModComments(modId: string, opts: { take?: number; cursor?: string } = {}): Promise<{ comments: ModComment[]; nextCursor: string | null }> {
228	  const take = opts.take ?? 10;
229	  const rows = await db.modRating.findMany({
230	    where: { gameModId: modId, comment: { not: null } },
231	    orderBy: { createdAt: "desc" },
232	    take: take + 1,
233	    ...(opts.cursor ? { cursor: { id: opts.cursor }, skip: 1 } : {}),
234	    include: { user: { select: { id: true, name: true } } },
235	  });
236	  const page = rows.slice(0, take);
237	  const nextCursor = rows.length > take ? page[page.length - 1]!.id : null;
238	  return {
239	    comments: page.map((r) => ({
240	      id: r.id,
241	      rating: r.rating,
242	      comment: r.comment!,
243	      createdAt: r.createdAt.toISOString(),
244	      userId: r.userId,
245	      userName: r.user.name,
246	    })),
247	    nextCursor,
248	  };
249	}
250	
251	/** This viewer's own rating/comment on a mod, if they've left one — prefills the form as an edit rather than a fresh submit. */
252	export async function getMyModRating(modId: string, userId: string): Promise<{ rating: number; comment: string | null } | null> {
253	  const row = await db.modRating.findUnique({ where: { userId_gameModId: { userId, gameModId: modId } } });
254	  return row ? { rating: row.rating, comment: row.comment } : null;
255	}
256	
257	/**
258	 * Real, case-insensitive search over name/category/description for one
259	 * family (or the whole catalog when family is omitted) — backs both the
260	 * marketing and portal search bars. Small catalogue, so a plain `findMany`
261	 * with `contains` is genuinely fine; no search index needed at this scale.
262	 */
263	export async function searchCatalogMods(query: string, family?: string): Promise<ModSummary[]> {
264	  const q = query.trim();
265	  if (!q) return listCatalogMods(family);
266	  const rows = await db.gameMod.findMany({
267	    where: {
268	      active: true,
269	      upstreamOk: true,
270	      ...(family ? { gameFamily: family } : {}),
271	      OR: [
272	        { name: { contains: q, mode: "insensitive" } },
273	        { category: { contains: q, mode: "insensitive" } },
274	        { description: { contains: q, mode: "insensitive" } },
275	      ],
276	    },
277	    orderBy: [{ featured: "desc" }, { downloads: "desc" }, { name: "asc" }],
278	    take: CATALOG_LIST_CAP,
279	  });
280	  const aggs = await ratingAggs(rows.map((r) => r.id));
281	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
282	}
283	
284	export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;
285	
286	/**
287	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
288	 * light-impact mods run on any active plan for the family; moderate needs at
289	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
290	 * for the family that clears the bar, or null if none does (never guesses a
291	 * number that isn't a real, active, orderable plan).
292	 */
293	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
294	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
295	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
296	  const pick = candidates[0];
297	  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
298	}
299	
300	export function formatDownloads(n: number | null): string | null {
301	  if (n == null) return null;
302	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
303	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
304	  return String(n);
305	}
306	
307	export function formatBytes(bytes: number | null): string | null {
308	  if (!bytes || bytes <= 0) return null;
309	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
310	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
311	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
312	}
313	
314	/**
315	 * The real, authoritative download for a mod detail page. Prefers the
316	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
317	 * install it) so a visitor gets the actual file, not just a landing page;
318	 * falls back to the mod's own project/resource page (still the real,
319	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
320	 * be resolved live or isn't one of the three we know how to resolve.
321	 */
322	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
323	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
324	  const id = mod.sourceId ?? "";
325	  if (!id) return fallback;
326	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
327	  try {
328	    if (mod.source === "modrinth") {
329	      const headers: Record<string, string> = { "User-Agent": UA };
330	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
331	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
332	      if (!res.ok) return fallback;
333	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
334	      const v = versions[0];
335	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
336	      return file ? { url: file.url, direct: true } : fallback;
337	    }
338	    if (mod.source === "spigotmc") {
339	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
340	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
341	    }
342	    if (mod.source === "thunderstore") {
343	      const [namespace, ...rest] = id.split("-");
344	      if (!namespace || !rest.length) return fallback;
345	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
346	        headers: { "User-Agent": UA },
347	        next: { revalidate: 3600 },
348	      });
349	      if (!res.ok) return fallback;
350	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
351	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
352	    }
353	  } catch {
354	    return fallback;
355	  }
356	  return fallback;
357	}
358	
359	export const SOURCE_LABEL: Record<string, string> = {
360	  modrinth: "Modrinth",
361	  spigotmc: "SpigotMC",
362	  hangar: "Hangar",
363	  curseforge: "CurseForge",
364	  steam_workshop: "Steam Workshop",
365	  umod: "uMod",
366	  github: "GitHub",
367	  nexus: "Nexus Mods",
368	  thunderstore: "Thunderstore",
369	  codefling: "Codefling",
370	};
