1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { requireUser } from "@/lib/auth";
4	import { db } from "@/lib/db";
5	import { PageShell } from "@/components/nx/PageShell";
6	import { ModCard } from "@/components/mods/ModCard";
7	import { AddToServerWidget } from "@/components/mods/AddToServerWidget";
8	import { AuthorBadge } from "@/components/mods/AuthorBadge";
9	import { GalleryStrip } from "@/components/mods/GalleryStrip";
10	import { RatingsAndComments } from "@/components/mods/RatingsAndComments";
11	import {
12	  getCatalogMod,
13	  relatedCatalogMods,
14	  recommendedPlanFor,
15	  resolveDownloadUrl,
16	  listModComments,
17	  getMyModRating,
18	  formatDownloads,
19	  formatBytes,
20	  SOURCE_LABEL,
21	} from "@/lib/mods-catalog";
22	
23	export const dynamic = "force-dynamic";
24	
25	/**
26	 * Portal's own mod-detail route — genuinely separate from the public
27	 * /mods/[family]/[slug] page (item 1 of the NxLabs brief). Same underlying
28	 * data (lib/mods-catalog.ts), rendered through the Nexion portal shell by
29	 * virtue of living under app/dashboard/**, with its own breadcrumbs back
30	 * into /dashboard/nxlabs instead of the public catalog.
31	 */
32	export default async function PortalModDetailPage({ params }: { params: Promise<{ family: string; slug: string }> }) {
33	  const { family, slug } = await params;
34	  const user = await requireUser();
35	  const mod = await getCatalogMod(family, slug);
36	  if (!mod) notFound();
37	
38	  const [gamePlans, related, download, commentsPage, myRating] = await Promise.all([
39	    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
40	    relatedCatalogMods(mod, 4),
41	    resolveDownloadUrl(mod),
42	    listModComments(mod.id, { take: 10 }),
43	    getMyModRating(mod.id, user.id),
44	  ]);
45	  const recommended = recommendedPlanFor(mod, gamePlans);
46	  const downloads = formatDownloads(mod.downloads);
47	  const fileSize = formatBytes(mod.fileBytes);
48	
49	  return (
50	    <PageShell eyebrow="NxLabs" title={mod.name} sub={mod.description ?? undefined} tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}>
51	      <p className="-mt-2 mb-4 text-xs text-tx-mute">
52	        <Link href="/dashboard/nxlabs" className="hover:underline">
53	          NxLabs
54	        </Link>{" "}
55	        /{" "}
56	        <Link href={`/dashboard/nxlabs/games/${mod.gameFamily}`} className="hover:underline">
57	          {mod.gameFamilyLabel}
58	        </Link>
59	      </p>
60	
61	      <div className="grid gap-8 lg:grid-cols-[1.4fr_1fr]">
62	        <div className="space-y-6">
63	          <div className="flex flex-wrap items-center gap-4">
64	            {mod.iconUrl && (
65	              // eslint-disable-next-line @next/next/no-img-element
66	              <img src={mod.iconUrl} alt="" className="h-16 w-16 rounded-2xl border border-white/10 object-cover" />
67	            )}
68	            {mod.authorName && <AuthorBadge name={mod.authorName} avatarUrl={mod.authorAvatarUrl} />}
69	          </div>
70	
71	          {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}
72	
73	          <div className="card p-6">
74	            <h2 className="text-lg font-semibold text-white">Download</h2>
75	            {download ? (
76	              <>
77	                <a href={download.url} className="btn-primary mt-4 inline-flex" target="_blank" rel="noopener noreferrer nofollow">
78	                  {download.direct ? "Download file" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
79	                </a>
80	                <p className="mt-2 text-xs text-tx-mute">
81	                  Hosted by {SOURCE_LABEL[mod.source] ?? mod.source} — Nxeon never mirrors or stores mod files.
82	                </p>
83	              </>
84	            ) : (
85	              <p className="mt-3 text-sm text-tx-mute">No download link is available for this entry right now.</p>
86	            )}
87	            <div className="mt-6">
88	              <AddToServerWidget modId={mod.id} gameFamily={mod.gameFamilyLabel} downloadUrl={download?.url ?? null} />
89	            </div>
90	            {!mod.upstreamOk && (
91	              <p className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
92	                {mod.upstreamNote || "This mod is no longer supported by its source."}
93	              </p>
94	            )}
95	          </div>
96	
97	          <RatingsAndComments
98	            modId={mod.id}
99	            avgRating={mod.avgRating}
100	            ratingCount={mod.ratingCount}
101	            initialComments={commentsPage.comments}
102	            initialCursor={commentsPage.nextCursor}
103	            myRating={myRating}
104	            isLoggedIn
105	            isAdmin={user.role === "ADMIN"}
106	            loginHref="/login"
107	          />
108	        </div>
109	
110	        <aside className="space-y-6">
111	          <div className="card p-6">
112	            <h2 className="text-sm font-semibold uppercase tracking-wide text-tx-mute">Details</h2>
113	            <dl className="mt-4 space-y-3 text-sm">
114	              <Row label="Game">{mod.gameFamilyLabel}</Row>
115	              <Row label="Category">{mod.category}</Row>
116	              <Row label="Source">{SOURCE_LABEL[mod.source] ?? mod.source}</Row>
117	              {mod.license && <Row label="License">{mod.license}</Row>}
118	              {downloads && <Row label="Downloads">{downloads}</Row>}
119	              {fileSize && <Row label="File size">{fileSize}</Row>}
120	              {mod.gameVersions.length > 0 && <Row label="Game versions">{mod.gameVersions.slice(-6).reverse().join(", ")}</Row>}
121	              {mod.loaders.length > 0 && <Row label="Loaders">{mod.loaders.join(", ")}</Row>}
122	              {mod.appliesToVariant && <Row label="Requires">{mod.appliesToVariant} server type</Row>}
123	              {mod.serverSide && <Row label="Server support">{mod.serverSide}</Row>}
124	              <Row label="Verified">{mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}</Row>
125	            </dl>
126	          </div>
127	
128	          <div className="card p-6">
129	            <h2 className="text-sm font-semibold uppercase tracking-wide text-tx-mute">Recommended server</h2>
130	            {recommended ? (
131	              <p className="mt-3 text-sm text-tx-mute">
132	                Works well on <span className="text-white">{recommended.planName}</span> (
133	                {(recommended.ramMB / 1024).toFixed(recommended.ramMB % 1024 ? 1 : 0)} GB RAM) or higher —{" "}
134	                <Link href="/dashboard/deploy" className="text-brand-300 underline underline-offset-2">
135	                  deploy one
136	                </Link>
137	                .
138	              </p>
139	            ) : (
140	              <p className="mt-3 text-sm text-tx-mute">
141	                {mod.impactNote || "This is a light install and should run fine on any active plan for this game."}
142	              </p>
143	            )}
144	          </div>
145	        </aside>
146	      </div>
147	
148	      {related.length > 0 && (
149	        <div className="mt-12">
150	          <h2 className="text-lg font-semibold text-white">More for {mod.gameFamilyLabel}</h2>
151	          <div className="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
152	            {related.map((r) => (
153	              <ModCard key={r.id} mod={r} href={`/dashboard/nxlabs/${r.gameFamily}/${r.slug}`} />
154	            ))}
155	          </div>
156	        </div>
157	      )}
158	    </PageShell>
159	  );
160	}
161	
162	function Row({ label, children }: { label: string; children: React.ReactNode }) {
163	  return (
164	    <div className="flex items-start justify-between gap-4">
165	      <dt className="text-tx-mute">{label}</dt>
166	      <dd className="text-right text-white">{children}</dd>
167	    </div>
168	  );
169	}
